return {
  { "plain", "plain text\n" },
  { "empty source", "" },
  { "expression", 'before{{ "VALUE" }}after\n' },
  { "adjacent actions", '{{ "A" }}{{ "B" }}' },
  { "trim does not eat action output", '{{ " A " -}}{{- " B " }}' },
  { "indistinguishable literal text", 'same{{ "same" }}same{{ range (list 1 2) }}same{{ end }}' },
  { "empty true if", "{{ if true }}{{ end }}" },
  { "empty false if", "{{ if false }}{{ end }}" },
  { "empty else", "{{ if false }}{{ else }}{{ end }}" },
  { "else if", "A{{ if false }}B{{ else if true }}C{{ else }}D{{ end }}E" },
  { "data branch", "A{{ if .enabled }}B{{ else }}C{{ end }}D" },
  { "range", '{{ range (list "a" "b" "c") }}item={{ . }};{{ end }}tail' },
  { "empty range", "A{{ range (list) }}B{{ else }}C{{ end }}D" },
  { "nested", "{{ range (list 1 2 3) }}[{{ if eq . 2 }}skip{{ else }}{{ . }}{{ end }}]{{ end }}" },
  { "with", '{{ with (dict "name" "nvim") }}name={{ .name }}{{ else }}none{{ end }}' },
  { "variables", '{{ $x := "one" }}A{{ $x = "two" }}B{{ $x }}C' },
  { "left trim", 'before \t\r\n{{- "X" }} after' },
  { "right trim", 'before {{ "X" -}}\r\n\t after' },
  { "both trims", 'a \n{{- "X" -}}\n b' },
  { "overlapping trim", '{{ "A" -}} \t\r\n {{- "B" }}' },
  { "trim at empty if", "before\n{{- if true }}\n{{- end }}\nafter\n" },
  { "trim at false if", "before\n{{- if false }}\n{{- end }}\nafter\n" },
  { "trimmed range", "head\n{{- range (list 1 2) -}}\n [{{ . }}] \n{{- end -}}\n tail" },
  { "negative literal is not trim", "before {{-3}} after" },
  { "unicode", '中文\194\160{{- "动态" -}}\194\160结束\n' },
  { "comment", "before{{/* {{ embedded }} */}}after" },
  { "trimmed comment", "before \n{{- /* comment */ -}}\n after" },
  { "escaped braces", 'before{{ "{{" }}x{{ "}}" }}after' },
  { "raw string action", "before{{ `{{ not an action }}` }}after" },
  { "quoted closing delimiter", 'before{{ printf "%s" "}}" }}after' },
  { "definition", '{{ define "greet" }}Hello {{ . }}!{{ end }}{{ template "greet" "nvim" }}' },
  {
    "repeated template calls",
    '{{ define "item" }}[{{ . }}]{{ end }}{{ template "item" "A" }}{{ template "item" "B" }}',
  },
  { "block", '{{ block "slot" . }}default={{ .enabled }}{{ end }}' },
  { "nested block", '{{ block "outer" . }}a{{ block "inner" . }}b{{ end }}c{{ end }}{{ template "inner" . }}' },
  { "trimmed definition", 'before \n{{- define "x" -}} X {{- end -}}\n{{ template "x" . }} after' },
  { "trimmed block", 'before \n{{- block "x" . -}} X {{- end -}}\n after' },
  {
    "empty definition override",
    '{{ define "x" }}original{{ end }}{{ define "x" }} {{/* empty */}}{{ end }}{{ template "x" . }}',
  },
  { "empty block override", '{{ block "x" . }} {{/* empty */}}{{ end }}{{ define "x" }}replacement{{ end }}' },
  { "continue", "{{ range (list 1 2 3) }}{{ if eq . 2 }}{{ continue }}{{ end }}[{{ . }}]{{ end }}" },
  { "break", "{{ range (list 1 2 3) }}[{{ . }}]{{ if eq . 2 }}{{ break }}{{ end }}{{ end }}" },
  { "include template", '{{ includeTemplate "external" . }}' },
  {
    "init function",
    '{{ if false }}{{ promptChoiceOnce . "demo" "Choose" (list "a" "b") "a" }}{{ end }}',
    { init = true },
  },
}
